<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Alert</span><span class="s_1i4ay4"> title</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Saved</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> theme</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">green</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
